std::string Read(const std::filesystem::path& p){std::ifstream in(p,std::ios::binary);return {std::istreambuf_iterator<char>(in),{}};}
template<class F>void Reject(F f){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}assert(rejected);}
void NoPolicyTestcases(const std::filesystem::path& path,size_t count){const auto xml=Read(path);assert(xml.find("tests=\""+std::to_string(count)+"\"")!=xml.npos&&xml.find("failures=\"0\"")!=xml.npos&&xml.find("errors=\"0\"")!=xml.npos&&xml.find("<error ")==xml.npos&&xml.find("<failure ")==xml.npos);size_t rows=0,at=0;while((at=xml.find("<testcase ",at))!=xml.npos){++rows;++at;}assert(rows==count);}
void Replace(std::string& text,std::string_view from,std::string_view to){const auto at=text.find(from);assert(at!=text.npos);text.replace(at,from.size(),to);}
